<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\Template\Domain\ValueObject;

use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;

class TemplateTenantVO
{
  public static function empty(): TemplateTenantVO
  {
      return new TemplateTenantVO(null);
  }
  public static function from(TemplateTenantVO|TenantRef|null $value): TemplateTenantVO
  {
    return self::fromUnsafe($value);
  }
  public static function tryFrom(mixed $value, ConstraintFailList $list): ?TemplateTenantVO
  {
    if ( $value instanceof TemplateTenantVO ) {
      // If is a ValueObject, its already validated... nothing to append
      return $value;
    } else if( !$value ) {
      return new TemplateTenantVO($value);
    } else if( is_a($value, TenantRef::class)) {
      return new TemplateTenantVO($value);
    } else {
      $list->add(new ConstraintFail('wrong_type', ['tenant'], [$value], ['TenantRef']));
      return null;
    }
  }
  private static function fromUnsafe(mixed $value): TemplateTenantVO
  {
    if ($value instanceof TemplateTenantVO) {
      // If is a ValueObject, its already validated
      return $value;
    } else {
      // If is not a ValueObject, validation is need and exception throw
      $errorsList = new ConstraintFailList();
      $candidate = self::tryFrom($value, $errorsList);
      if ($errorsList->hasErrors()) {
        throw $errorsList->asConstraintException();
      }
      \assert($candidate instanceof TemplateTenantVO);
      return $candidate;
    }
  }
  /**
   * private constructor to avoid build a value without all the rule validations.
   */
  private function __construct(
    private readonly ?TenantRef $tenant
  ) {
  }
  public function value(): ?TenantRef
  {
    return $this->tenant;
  }
  public function equals(?TemplateTenantVO $other): bool
  {
    return $this->value()?->uid() == $other?->value()?->uid();
  }
}
